  }
   if (!is.null(input$stat_name)){
    statN<-input$stat_name
  }else{
     statN<-levels(myData$name)[1]
  }

  g1<-myData %>% filter(partner_name == part,name == statN)
  g1
})

lb <- reactive({linked_brush(keys = react2()$id, "red") })

tt<-reactive({

 elem1<- react2() %>%
